import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); int reversed = 0; while (n > 0) { reversed = reversed * 10 + (n % 10); n /= 10; } out.println(reversed); } } out.flush(); out.close(); } }